279	// appendLine marshals a transcriptLine and appends it (with newline) to result.
280	func appendLine(result *[]byte, line transcriptLine) {
281		b, err := json.Marshal(line)
282		if err != nil {
283			return
284		}
285		*result = append(*result, b...)
286		*result = append(*result, '\n')
287	}
288	
289	// parseJSONLEntries parses all JSONL lines into intermediate entries,
290	// filtering dropped types and malformed lines.
291	func parseJSONLEntries(content []byte, preprocess linePreprocessor) ([]parsedEntry, error) {
292		reader := bufio.NewReader(bytes.NewReader(content))
293		var entries []parsedEntry
294	
295		for {
296			lineBytes, err := reader.ReadBytes('\n')
297			if err != nil && err != io.EOF {
298				return nil, fmt.Errorf("reading JSONL line: %w", err)
299			}
300	
301			if len(bytes.TrimSpace(lineBytes)) > 0 {
302				if e, ok := parseLine(lineBytes, preprocess); ok {
303					entries = append(entries, e)
304				}
305			}
306	
307			if err == io.EOF {
308				break
309			}
310		}
311	
312		return entries, nil
313	}
314	
315	// parseLine converts a single JSONL line into a parsedEntry.
316	// Returns ok=false for dropped/malformed lines.
317	func parseLine(lineBytes []byte, preprocess linePreprocessor) (parsedEntry, bool) {
318		var raw map[string]json.RawMessage
319		if err := json.Unmarshal(lineBytes, &raw); err != nil {
320			return parsedEntry{}, false
321		}
322	
323		if preprocess != nil {
324			raw = preprocess(raw)
325		}
326	
327		kind := normalizeKind(raw)
328		if kind == "" {
329			return parsedEntry{}, false
330		}
331	
332		e := parsedEntry{
333			kind: kind,
334			ts:   raw["timestamp"],
335		}
336	
337		msg := parseMessage(raw)
338	
339		switch kind {
340		case transcript.TypeAssistant:
341			if msg != nil {
342				e.id = unquote(msg["id"])
343				if contentRaw, ok := msg["content"]; ok {
344					e.content = stripAssistantContent(contentRaw)
345				}
346				e.inputTokens, e.outputTokens = extractUsageTokens(msg)
347			}
348	
349		case transcript.TypeUser:
350			e.userID = unquote(raw["promptId"])
351			if msg != nil {
352				if contentRaw, ok := msg["content"]; ok {
353					uc := extractUserContent(contentRaw)
354					e.userText = uc.text
355					e.userImages = uc.images
356					e.toolResults = uc.toolResults
357				}
358			}
359			// Enrich tool results with metadata from toolUseResult.
360			if turRaw, ok := raw["toolUseResult"]; ok {
361				var tur map[string]json.RawMessage
362				if json.Unmarshal(turRaw, &tur) == nil {
363					e.toolResults = enrichToolResults(e.toolResults, tur)
364				}
365			}
366		}
367	
368		return e, true
369	}
